function rotateLeftOne(arr) {
  if (arr.length < 2) return arr.slice()
  return [...arr.slice(1), arr[0]]
}

function charCount(str) {
  const m = new Map()
  for (const ch of str) m.set(ch, (m.get(ch) || 0) + 1)
  return Object.fromEntries(m)
}

